import{_ as e,C as o,o as n,c as s,j as a,a as i,G as d,a3 as l}from"./chunks/framework.B6x8LOwa.js";const f=JSON.parse('{"title":"智能笔迹处理","description":"ICC-CE 的笔迹拉直、形状识别、端点吸附及多样化绘图工具使用指南","frontmatter":{"title":"智能笔迹处理","description":"ICC-CE 的笔迹拉直、形状识别、端点吸附及多样化绘图工具使用指南"},"headers":[],"relativePath":"cn/guide/smart-ink-processing.md","filePath":"cn/guide/smart-ink-processing.md"}'),h={name:"cn/guide/smart-ink-processing.md"};function c(g,t,u,b,p,m){const r=o("ArticleMetadata");return n(),s("div",null,[t[0]||(t[0]=a("h1",{id:"智能笔迹处理",tabindex:"-1"},[i("智能笔迹处理 "),a("a",{class:"header-anchor",href:"#智能笔迹处理","aria-label":'Permalink to "智能笔迹处理"'},"​")],-1)),d(r),t[1]||(t[1]=l('<p>ICC-CE 提供了强大的墨迹渲染与手绘辅助功能，能够在绘图和书写时自动对笔迹进行平滑、拉直与形状优化。</p><h2 id="智能绘图辅助" tabindex="-1">智能绘图辅助 <a class="header-anchor" href="#智能绘图辅助" aria-label="Permalink to &quot;智能绘图辅助&quot;">​</a></h2><h3 id="线条拉直功能" tabindex="-1">线条拉直功能 <a class="header-anchor" href="#线条拉直功能" aria-label="Permalink to &quot;线条拉直功能&quot;">​</a></h3><p>当绘制接近直线的笔画时，ICC-CE 可以自动识别并将其转换为完美直线。您可以通过设置调整灵敏度和阈值：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>可调范围</th></tr></thead><tbody><tr><td><strong>灵敏度设置</strong></td><td>控制系统对线条直线度的判断标准</td><td>0.05 - 2.0</td></tr><tr><td><strong>长度阈值</strong></td><td>只有超过设定长度的线条才会被考虑自动拉直</td><td>视像素数值调节</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">使用建议</p><p>在绘制几何图形或标注对齐线条时，适当提高灵敏度可以获得更精准的直线效果。</p></div><h3 id="形状识别" tabindex="-1">形状识别 <a class="header-anchor" href="#形状识别" aria-label="Permalink to &quot;形状识别&quot;">​</a></h3><p>自动识别并优化手绘图形，使其转换为标准几何形状：</p><ul><li><strong>矩形和正方形</strong></li><li><strong>三角形</strong></li><li><strong>圆形和椭圆</strong></li></ul><h3 id="端点吸附" tabindex="-1">端点吸附 <a class="header-anchor" href="#端点吸附" aria-label="Permalink to &quot;端点吸附&quot;">​</a></h3><p>绘制线条时，线条端点会自动吸附到附近的其他端点，便于快速创建封闭或连接良好的复杂几何图形。</p><hr><h2 id="多样化绘图工具" tabindex="-1">多样化绘图工具 <a class="header-anchor" href="#多样化绘图工具" aria-label="Permalink to &quot;多样化绘图工具&quot;">​</a></h2><h3 id="笔与荧光笔" tabindex="-1">笔与荧光笔 <a class="header-anchor" href="#笔与荧光笔" aria-label="Permalink to &quot;笔与荧光笔&quot;">​</a></h3><ul><li><strong>粗细与透明度</strong>：支持动态调节画笔粗细与不透明度</li><li><strong>预设颜色</strong>：内置丰富的调色板与快捷颜色选择</li><li><strong>压感支持</strong>：在支持压感的手绘板或主动式电容笔设备上，自动响应书写力度</li></ul><h3 id="触摸模式与优化" tabindex="-1">触摸模式与优化 <a class="header-anchor" href="#触摸模式与优化" aria-label="Permalink to &quot;触摸模式与优化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>特性</th></tr></thead><tbody><tr><td><strong>指尖绘图</strong></td><td>针对普通触摸屏优化，支持使用手指直接绘制</td></tr><tr><td><strong>笔尖模式</strong></td><td>专为手写笔设计的精确绘图模式，防误触体验更佳</td></tr><tr><td><strong>模拟压感</strong></td><td>在不支持硬件压感的设备上，根据书写速度动态模拟压感粗细变化</td></tr></tbody></table><h3 id="橡皮擦功能" tabindex="-1">橡皮擦功能 <a class="header-anchor" href="#橡皮擦功能" aria-label="Permalink to &quot;橡皮擦功能&quot;">​</a></h3><ul><li><strong>点擦模式</strong>：精确擦除笔画的局部重叠部分</li><li><strong>笔画擦除</strong>：点击笔画即可一次性擦除整条笔迹</li><li><strong>形状与大小</strong>：支持调整橡皮擦作用域的大小和覆盖形状</li></ul>',19))])}const k=e(h,[["render",c]]);export{f as __pageData,k as default};
